    {
      "service": "sync-job",
      "kind": "resource_exhaustion",
      "mechanism": "Sync-job exhausted its disk quota, causing ledger export write failures and sync errors.",
      "supporting": ["E16", "E4", "E7"],
      "refuting": ["E21"],
      "explains": ["E4", "E7", "E16"],
